function report = run_cad_cavity_screen()
%RUN_CAD_CAVITY_SCREEN Geometry-derived screening of the ambient-cavity assumption.
% This is a declared 1D vent-impedance proxy, not internal-flow CFD or a
% calibrated duct model. Original span ports are identified by boundary loops.
root=fileparts(fileparts(mfilename('fullpath')));c=cad.load_case(root,fullfile(root,'cases/cad_original/extruded-fine.json'));ports=jsondecode(fileread(fullfile(root,'results/cad_original/geometry_metrics/cavity_ports.json')));s=load(fullfile(root,'results/cad_original/aeroelastic_primary/reduced_cad.mat'),'bundle');p=load(fullfile(root,'results/cad_original/aeroelastic_primary/basis.mat'),'basis');m=s.bundle.model;mesh=fem3d.elevate(fem3d.read_mesh(fullfile(root,string(c.discretization.meshes{end})),c.geometry.axisOrder,c.geometry.origin_m));labels=cad.face_labels(mesh);omega=sqrt(m.K(1,1));rho=c.flow.rho_kg_m3;mu=c.flow.mu_Pa_s;b=c.geometry.span_m;sound=sqrt(1.4*287.05*288.15);delta=sqrt(2*mu/(rho*omega));M=zeros(size(m.K));C=M;closed=M;rows=[];volumeGradient=[];amplitude=1e-5/max(abs(m.observation(:,1)));
for k=1:numel(ports.loops)
 port=ports.loops(k);if strcmp(port.kind,'outer'),continue;end
 faces=mesh.faces(ismember(labels,port.cad_faces),:);F=fem3d.traction(mesh,faces,1);gradient=reshape(F',[],1)'*p.basis;A=port.area_m2;perimeter=port.perimeter_m;Dh=port.hydraulic_diameter_m;
 inertance=rho*b/(4*A);steady=48*mu*b/(4*A*Dh^2);stokes=mu*perimeter*b/(4*A^2*delta);resistance=max(steady,stokes);dV=abs(gradient(1)*amplitude);pressure=hypot(inertance*omega^2*dV,resistance*omega*dV);
 M=M+inertance*(gradient'*gradient);C=C+resistance*(gradient'*gradient);closed=closed+rho*sound^2/(A*b)*(gradient'*gradient);
 rows(end+1,:)=[port.loop,A,Dh,dV,pressure,inertance*gradient(1)^2,resistance*gradient(1)^2,omega*Dh/2*sqrt(rho/(mu*omega))];volumeGradient(end+1,:)=gradient; %#ok<AGROW>
end
report=array2table(rows,'VariableNames',{'loop','port_area_each_end_m2','hydraulic_diameter_m','volume_amplitude_m3_at_TE10um','pressure_proxy_Pa_at_TE10um','added_modal_mass_proxy','added_modal_damping_proxy_per_s','Womersley'});out=fullfile(root,'results/cad_original/cavity_screen');if ~isfolder(out),mkdir(out);end;writetable(report,fullfile(out,'ports.csv'));scope=struct('openPorts',true,'model','two equal open span ends, lumped midspan volume source; uniform span breathing has one third of this inertance','modalMassRatioProxy',M(1,1),'modalDampingRatioToAssumedStructural',C(1,1)/m.C(1,1),'maximumPressureProxy_Pa',max(rows(:,5)),'closedPortStiffnessRatioProxy',closed(1,1)/m.K(1,1),'screeningOnly',true,'limitations','noncircular hydraulic approximation and oscillatory wall-layer proxy; not a certified bound or measured ventilation impedance','primaryAssumption','ambient cavity pressure; interior walls receive no imposed exterior aerodynamic pressure');cad.write_json(fullfile(out,'scope.json'),scope);save(fullfile(out,'operators.mat'),'M','C','closed','volumeGradient','scope');disp(scope);
end
